def buildFromDescriptions(descriptions):
    left, right = {}, {}
    parents, kids = set(), set()
    for p, c, is_left in descriptions:
        parents.add(p)
        kids.add(c)
        if is_left:
            left[p] = c
        else:
            right[p] = c
    root = next(iter(parents - kids))
    out = []
    queue = [root]
    for x in queue:
        if x == -1:
            out.append(-1)
        else:
            out.append(x)
            queue.append(left.get(x, -1))
            queue.append(right.get(x, -1))
    while out and out[-1] == -1:
        out.pop()
    return out
